diff --git a/src/posts/cache.js b/src/posts/cache.js
index 7f4711d0cd..83a69fd736 100644
--- a/src/posts/cache.js
+++ b/src/posts/cache.js
@@ -3,10 +3,74 @@
 const cacheCreate = require('../cache/lru');
 const meta = require('../meta');

-module.exports = cacheCreate({
-	name: 'post',
-	maxSize: meta.config.postCacheSize,
-	sizeCalculation: function (n) { return n.length || 1; },
-	ttl: 0,
-	enabled: global.env === 'production',
+let cache;
+
+function getOrCreate() {
+	if (!cache) {
+		const postCacheSize = meta.config.postCacheSize || 20971520;
+		cache = cacheCreate({
+			name: 'post',
+			maxSize: postCacheSize,
+			sizeCalculation: function (n) { return n.length || 1; },
+			ttl: 0,
+			enabled: global.env === 'production',
+		});
+	}
+	return cache;
+}
+
+function del(pid) {
+	if (!cache) {
+		return;
+	}
+	if (Array.isArray(pid)) {
+		cache.del(pid);
+		return;
+	}
+	const keys = ['default', 'plaintext', 'activitypub.note', 'activitypub.article']
+		.map(type => `${String(pid)}|${type}`);
+	cache.del(keys);
+}
+
+function reset() {
+	if (cache) {
+		cache.reset();
+	}
+}
+
+const postCache = {
+	getOrCreate,
+	del,
+	reset,
+};
+
+['get', 'set', 'has', 'dump', 'peek', 'getUnCachedKeys'].forEach((method) => {
+	postCache[method] = function (...args) {
+		return getOrCreate()[method](...args);
+	};
 });
+
+['name', 'hits', 'misses', 'enabled'].forEach((prop) => {
+	Object.defineProperty(postCache, prop, {
+		get: function () {
+			return getOrCreate()[prop];
+		},
+		set: function (value) {
+			getOrCreate()[prop] = value;
+		},
+		configurable: true,
+		enumerable: true,
+	});
+});
+
+['length', 'calculatedSize', 'max', 'maxSize', 'itemCount', 'size', 'ttl'].forEach((prop) => {
+	Object.defineProperty(postCache, prop, {
+		get: function () {
+			return getOrCreate()[prop];
+		},
+		configurable: true,
+		enumerable: true,
+	});
+});
+
+module.exports = postCache;
