@@ -0,0 +1,47 @@
+'use strict';
+
+const nconf = require('nconf');
+
+const user = require('../user');
+
+const Controllers = module.exports;
+
+function publicHost() {
+	try {
+		return new URL(nconf.get('url')).host;
+	} catch (err) {
+		return '';
+	}
+}
+
+Controllers.webfinger = async function (req, res) {
+	const resource = req.query && req.query.resource;
+	const match = /^acct:([^@]+)@(.+)$/.exec(resource || '');
+	if (!match || match[2] !== publicHost()) {
+		return res.status(400).json({ error: 'invalid_resource' });
+	}
+
+	const userslug = match[1];
+	const uid = await user.getUidByUserslug(userslug);
+	if (!uid) {
+		return res.status(404).json({ error: 'not_found' });
+	}
+
+	const userData = await user.getUserFields(uid, ['uid', 'username', 'userslug']);
+	const resolvedUid = userData.uid || uid;
+	const resolvedSlug = userData.userslug || userslug;
+	return res.json({
+		subject: resource,
+		aliases: [
+			`/uid/${resolvedUid}`,
+			`/user/${resolvedSlug}`,
+		],
+		links: [
+			{
+				rel: 'self',
+				type: 'text/html',
+				href: `/user/${resolvedSlug}`,
+			},
+		],
+	});
+};
