@@ -0,0 +1,34 @@
+export interface KeyCombo {
+    key: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+    ctrlOrCmd?: boolean;
+}
+
+type KeyEventLike = {
+    key?: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+};
+
+const isPressed = (value: boolean | undefined): boolean => value === true;
+
+export function isKeyComboMatch(ev: KeyEventLike, combo: KeyCombo, onMac: boolean): boolean {
+    const eventKey = String(ev.key ?? "").toLowerCase();
+    const comboKey = String(combo.key).toLowerCase();
+    if (eventKey !== comboKey) {
+        return false;
+    }
+
+    const expectedCtrl = combo.ctrlOrCmd === true ? onMac === false : combo.ctrlKey === true;
+    const expectedMeta = combo.ctrlOrCmd === true ? onMac === true : combo.metaKey === true;
+
+    return isPressed(ev.ctrlKey) === expectedCtrl &&
+        isPressed(ev.altKey) === (combo.altKey === true) &&
+        isPressed(ev.shiftKey) === (combo.shiftKey === true) &&
+        isPressed(ev.metaKey) === expectedMeta;
+}

