+
+export class FixedRollingArray<T> {
+    private readonly data: T[];
+
+    public constructor(private readonly width: number, padValue: T) {
+        this.data = new Array<T>(width).fill(padValue);
+    }
+
+    public get value(): T[] {
+        return this.data;
+    }
+
+    public pushValue(value: T): void {
+        this.data.unshift(value);
+        if (this.data.length > this.width) {
+            this.data.pop();
+        }
+    }
+}

