diff --git a/internal/server/audit/webhook/client.go b/internal/server/audit/webhook/client.go
new file mode 100644
index 00000000..c2afaf9e
--- /dev/null
+++ b/internal/server/audit/webhook/client.go
@@ -0,0 +1,94 @@
+package webhook
+
+import (
+	"bytes"
+	"context"
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"net/http"
+	"time"
+
+	"github.com/cenkalti/backoff/v4"
+	"go.flipt.io/flipt/internal/server/audit"
+)
+
+const signatureHeader = "x-flipt-webhook-signature"
+
+type Option func(*HTTPClient)
+
+type HTTPClient struct {
+	url                string
+	signingSecret      string
+	httpClient         *http.Client
+	maxBackoffDuration time.Duration
+}
+
+func NewClient(url, signingSecret string, opts ...Option) *HTTPClient {
+	c := &HTTPClient{
+		url:                url,
+		signingSecret:      signingSecret,
+		httpClient:         http.DefaultClient,
+		maxBackoffDuration: time.Minute,
+	}
+	for _, opt := range opts {
+		opt(c)
+	}
+	return c
+}
+
+func WithHTTPClient(client *http.Client) Option {
+	return func(c *HTTPClient) {
+		if client != nil {
+			c.httpClient = client
+		}
+	}
+}
+
+func WithMaxBackoffDuration(duration time.Duration) Option {
+	return func(c *HTTPClient) {
+		if duration > 0 {
+			c.maxBackoffDuration = duration
+		}
+	}
+}
+
+func (c *HTTPClient) SendAudit(ctx context.Context, event audit.Event) error {
+	payload, err := json.Marshal(event)
+	if err != nil {
+		return err
+	}
+
+	operation := func() error {
+		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.url, bytes.NewReader(payload))
+		if err != nil {
+			return err
+		}
+		req.Header.Set("Content-Type", "application/json")
+		if c.signingSecret != "" {
+			req.Header.Set(signatureHeader, sign(payload, c.signingSecret))
+		}
+
+		resp, err := c.httpClient.Do(req)
+		if err != nil {
+			return err
+		}
+		defer resp.Body.Close()
+		if resp.StatusCode != http.StatusOK {
+			return fmt.Errorf("failed to send event to webhook url: status %d", resp.StatusCode)
+		}
+		return nil
+	}
+
+	policy := backoff.NewExponentialBackOff()
+	policy.MaxElapsedTime = c.maxBackoffDuration
+	return backoff.Retry(operation, backoff.WithContext(policy, ctx))
+}
+
+func sign(payload []byte, secret string) string {
+	mac := hmac.New(sha256.New, []byte(secret))
+	mac.Write(payload)
+	return hex.EncodeToString(mac.Sum(nil))
+}
diff --git a/internal/server/audit/webhook/webhook.go b/internal/server/audit/webhook/webhook.go
new file mode 100644
index 00000000..a3e7e316
--- /dev/null
+++ b/internal/server/audit/webhook/webhook.go
@@ -0,0 +1,40 @@
+package webhook
+
+import (
+	"context"
+
+	"github.com/hashicorp/go-multierror"
+	"go.flipt.io/flipt/internal/server/audit"
+)
+
+const sinkType = "webhook"
+
+type Client interface {
+	SendAudit(context.Context, audit.Event) error
+}
+
+type Sink struct {
+	client Client
+}
+
+func NewSink(client Client) audit.Sink {
+	return &Sink{client: client}
+}
+
+func (s *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
+	var result error
+	for _, event := range events {
+		if err := s.client.SendAudit(ctx, event); err != nil {
+			result = multierror.Append(result, err)
+		}
+	}
+	return result
+}
+
+func (s *Sink) Close() error {
+	return nil
+}
+
+func (s *Sink) String() string {
+	return sinkType
+}

