+package ecr
+
+import (
+	"context"
+	"encoding/base64"
+	"errors"
+	"strings"
+
+	"github.com/aws/aws-sdk-go-v2/config"
+	awsecr "github.com/aws/aws-sdk-go-v2/service/ecr"
+	"oras.land/oras-go/v2/registry/remote/auth"
+)
+
+var ErrNoAWSECRAuthorizationData = errors.New("no AWS ECR authorization data")
+
+type Credential = auth.Credential
+type CredentialFunc = auth.CredentialFunc
+
+type Client interface {
+	GetAuthorizationToken(ctx context.Context, params *awsecr.GetAuthorizationTokenInput, optFns ...func(*awsecr.Options)) (*awsecr.GetAuthorizationTokenOutput, error)
+}
+
+type ECR struct {
+	client Client
+}
+
+func New(client Client) *ECR {
+	return &ECR{client: client}
+}
+
+func (e *ECR) Credential(ctx context.Context, hostport string) (auth.Credential, error) {
+	_ = hostport
+	if e.client == nil {
+		cfg, err := config.LoadDefaultConfig(ctx)
+		if err != nil {
+			return auth.EmptyCredential, err
+		}
+		if _, err := cfg.Credentials.Retrieve(ctx); err != nil {
+			return auth.EmptyCredential, err
+		}
+		e.client = awsecr.NewFromConfig(cfg)
+	}
+	return e.fetchCredential(ctx)
+}
+
+func (e *ECR) fetchCredential(ctx context.Context) (auth.Credential, error) {
+	output, err := e.client.GetAuthorizationToken(ctx, &awsecr.GetAuthorizationTokenInput{})
+	if err != nil {
+		return auth.EmptyCredential, err
+	}
+	if len(output.AuthorizationData) == 0 {
+		return auth.EmptyCredential, ErrNoAWSECRAuthorizationData
+	}
+	token := output.AuthorizationData[0].AuthorizationToken
+	if token == nil {
+		return auth.EmptyCredential, auth.ErrBasicCredentialNotFound
+	}
+	decoded, err := base64.StdEncoding.DecodeString(*token)
+	if err != nil {
+		return auth.EmptyCredential, err
+	}
+	parts := strings.Split(string(decoded), ":")
+	if len(parts) != 2 {
+		return auth.EmptyCredential, auth.ErrBasicCredentialNotFound
+	}
+	return auth.Credential{Username: parts[0], Password: parts[1]}, nil
+}
