+		if err != nil {
+			return nil, fmt.Errorf("listing flags: %w", err)
+		}
+
+		for _, f := range flagList.Flags {
+			existingFlags[f.Key] = true
+		}
+
+		nextPageToken = flagList.NextPageToken
+		if nextPageToken == "" {
+			break
+		}
+	}
