diff --git a/internal/storage/fs/oci/source.go b/internal/storage/fs/oci/source.go
new file mode 100644
index 0000000..28cdf6c
--- /dev/null
+++ b/internal/storage/fs/oci/source.go
@@ -0,0 +1,99 @@
+package oci
+
+import (
+	"context"
+	"time"
+
+	"github.com/opencontainers/go-digest"
+	"go.flipt.io/flipt/internal/containers"
+	"go.flipt.io/flipt/internal/oci"
+	storagefs "go.flipt.io/flipt/internal/storage/fs"
+	"go.uber.org/zap"
+)
+
+// Source is an implementation of storagefs.SnapshotSource backed by an OCI
+// repository. It caches the current snapshot by manifest digest.
+type Source struct {
+	logger   *zap.Logger
+	interval time.Duration
+	store    *oci.Store
+
+	curSnap   *storagefs.StoreSnapshot
+	curDigest digest.Digest
+}
+
+// NewSource constructs and configures an OCI snapshot source.
+func NewSource(logger *zap.Logger, store *oci.Store, opts ...containers.Option[Source]) (*Source, error) {
+	source := &Source{
+		logger:   logger,
+		interval: 30 * time.Second,
+		store:    store,
+	}
+	containers.ApplyAll(source, opts...)
+	return source, nil
+}
+
+// WithPollInterval configures how frequently the source checks for updates.
+func WithPollInterval(interval time.Duration) containers.Option[Source] {
+	return func(source *Source) {
+		source.interval = interval
+	}
+}
+
+func (*Source) String() string {
+	return "oci"
+}
+
+// Get returns the current OCI snapshot, rebuilding it only when the manifest
+// digest changes.
+func (s *Source) Get(ctx context.Context) (*storagefs.StoreSnapshot, error) {
+	response, err := s.store.Fetch(ctx, oci.IfNoMatch(s.curDigest))
+	if err != nil {
+		return nil, err
+	}
+
+	if response.Matched {
+		return s.curSnap, nil
+	}
+
+	snapshot, err := storagefs.SnapshotFromFiles(response.Files...)
+	if err != nil {
+		return nil, err
+	}
+
+	s.curSnap = snapshot
+	s.curDigest = response.Digest
+	return snapshot, nil
+}
+
+// Subscribe polls for changed OCI manifests until the context is cancelled.
+func (s *Source) Subscribe(ctx context.Context, snapshots chan<- *storagefs.StoreSnapshot) {
+	defer close(snapshots)
+
+	ticker := time.NewTicker(s.interval)
+	defer ticker.Stop()
+
+	for {
+		select {
+		case <-ctx.Done():
+			return
+		case <-ticker.C:
+			previous := s.curDigest
+			s.logger.Debug("fetching new snapshot", zap.String("current", previous.Hex()))
+
+			snapshot, err := s.Get(ctx)
+			if err != nil {
+				s.logger.Error("failed resolving upstream", zap.Error(err))
+				continue
+			}
+
+			if previous == s.curDigest {
+				s.logger.Debug("snapshot already up to date")
+				continue
+			}
+
+			snapshots <- snapshot
+			s.logger.Debug("fetched new reference from remote")
+		}
+	}
+}
