@@ -0,0 +1,45 @@
+package server
+
+import (
+	"context"
+	"time"
+
+	"github.com/gofrs/uuid"
+	flipt "github.com/markphelps/flipt/rpc"
+	"github.com/markphelps/flipt/storage"
+)
+
+// Evaluate evaluates a request for a given flag and entity.
+func (s *Server) Evaluate(ctx context.Context, req *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
+	if req.FlagKey == "" {
+		return nil, emptyFieldError("flagKey")
+	}
+	if req.EntityId == "" {
+		return nil, emptyFieldError("entityId")
+	}
+
+	startTime := time.Now()
+
+	if req.RequestId == "" {
+		req.RequestId = uuid.Must(uuid.NewV4()).String()
+	}
+
+	evaluator := s.Evaluator
+	if evaluator == nil {
+		// Preserve compatibility for callers that manually construct Server with
+		// the former concrete RuleStorage evaluator. New always injects the
+		// dedicated Evaluator dependency.
+		evaluator, _ = s.RuleStore.(storage.Evaluator)
+	}
+
+	resp, err := evaluator.Evaluate(ctx, req)
+	if err != nil {
+		return nil, err
+	}
+
+	if resp != nil {
+		resp.RequestDurationMillis = float64(time.Since(startTime)) / float64(time.Millisecond)
+	}
+
+	return resp, nil
+}
