+		}
+
+		port := d.Port
+		if port == 0 {
+			if d.Protocol == DatabaseProtocolPostgres {
+				port = 5432
+			} else {
+				port = 3306
+			}
+		}
+
+		u := url.URL{
+			Scheme: string(d.Protocol),
+			Host:   net.JoinHostPort(d.Host, fmt.Sprintf("%d", port)),
+			Path:   d.Name,
+		}
+		if d.User != "" {
