+func splitRPMQueryLine(line string, withRepository bool) ([]string, error) {
+	name, rest, ok := cutRPMField(strings.TrimSpace(line))
+	if !ok {
+		return nil, xerrors.Errorf("missing name")
+	}
+	epoch, rest, ok := cutRPMField(rest)
+	if !ok {
+		return nil, xerrors.Errorf("missing epoch")
+	}
+	version, rest, ok := cutRPMField(rest)
+	if !ok {
+		return nil, xerrors.Errorf("missing version")
+	}
+
+	separatorLen := len(rest) - len(strings.TrimLeft(rest, " "))
+	if separatorLen == 0 {
+		return nil, xerrors.Errorf("missing release separator")
+	}
+	rest = rest[separatorLen:]
+	release := ""
+	if separatorLen == 1 {
+		release, rest, ok = cutRPMField(rest)
+		if !ok {
+			return nil, xerrors.Errorf("missing release")
+		}
+	}
+	arch, rest, ok := cutRPMField(rest)
+	if !ok {
+		return nil, xerrors.Errorf("missing arch")
+	}
+	sourceRPM, rest, ok := cutRPMField(rest)
+	if !ok {
+		return nil, xerrors.Errorf("missing source rpm")
+	}
+
+	fields := []string{name, epoch, version, release, arch, sourceRPM}
+	rest = strings.TrimSpace(rest)
+	if withRepository {
+		if rest == "" {
+			return nil, xerrors.Errorf("missing repository")
+		}
+		fields = append(fields, rest)
+	} else if rest != "" {
+		fields = append(fields, rest)
+	}
+	return fields, nil
+}
+
+func cutRPMField(s string) (field, rest string, ok bool) {
+	s = strings.TrimLeft(s, " ")
+	if s == "" {
+		return "", "", false
+	}
+	if i := strings.IndexByte(s, ' '); i >= 0 {
+		return s[:i], s[i:], true
+	}
+	return s, "", true
+}
+
+func formatRPMVersion(epoch, version, release string) string {
+	if epoch != "" && epoch != "0" && epoch != "(none)" {
