+func mergeSeverityCveContent(contents []models.CveContent, content models.CveContent) []models.CveContent {
+	for i := range contents {
+		if contents[i].CveID == content.CveID {
+			contents[i].Cvss3Severity = mergeSeverityNames(contents[i].Cvss3Severity, content.Cvss3Severity)
+			return contents
+		}
+	}
+	return append(contents, content)
+}
+
+func mergeSeverityNames(values ...string) string {
+	seen := map[string]struct{}{}
+	for _, value := range values {
+		for _, part := range strings.Split(value, "|") {
+			part = strings.TrimSpace(part)
+			if part != "" {
+				seen[part] = struct{}{}
+			}
+		}
+	}
+	severities := make([]string, 0, len(seen))
+	for severity := range seen {
+		severities = append(severities, severity)
+	}
+	sort.Strings(severities)
+	return strings.Join(severities, "|")
