+		return nil, xerrors.Errorf("Failed to parse repoquery package line: %s", line)
+	}
+
+	ver := ""
+	epoch := fields[1]
+	if epoch == "0" || epoch == "(none)" {
+		ver = fields[2]
+	} else {
+		ver = fmt.Sprintf("%s:%s", epoch, fields[2])
+	}
+
+	arch := ""
+	repository := fields[4]
+	if len(fields) == 6 {
+		arch = fields[4]
+		repository = fields[5]
+	}
+
+	return &models.Package{
+		Name:       fields[0],
+		Version:    ver,
+		Release:    fields[3],
+		Arch:       arch,
+		Repository: normalizeAmazonRepository(repository),
+	}, nil
