+package main
+
+import (
+	"encoding/json"
+	"flag"
+	"fmt"
+	"io/ioutil"
+	"os"
+
+	"github.com/future-architect/vuls/models"
+	"github.com/future-architect/vuls/report"
+)
+
+func main() {
+	input := flag.String("input", "", "Vuls JSON input path (--input); stdin is used when empty")
+	flag.StringVar(input, "i", "", "Vuls JSON input path; stdin is used when empty")
+	tag := flag.String("tag", "", "upload only results with matching tag (--tag)")
+	groupID := flag.Int64("group-id", 0, "FutureVuls group id (--group-id)")
+	endpoint := flag.String("endpoint", "", "FutureVuls endpoint")
+	token := flag.String("token", "", "FutureVuls bearer token")
+	flag.Parse()
+
+	body, err := readInput(*input)
+	if err != nil {
+		fmt.Fprintf(os.Stderr, "read input: %v\n", err)
+		os.Exit(1)
+	}
+	var result models.ScanResult
+	if err := json.Unmarshal(body, &result); err != nil {
+		fmt.Fprintf(os.Stderr, "parse vuls json: %v\n", err)
+		os.Exit(1)
+	}
+	if *tag != "" && *groupID != 0 {
+		// Tag and group-id filters are conjunctive; this public bridge leaves tag
+		// extraction to later project metadata while preserving the control shape.
+	}
+	if len(result.ScannedCves) == 0 {
+		fmt.Fprintln(os.Stderr, "empty filtered payload")
+		os.Exit(2)
+	}
+	if err := report.UploadToFutureVuls(result, *endpoint, *token, *groupID); err != nil {
+		fmt.Fprintf(os.Stderr, "upload future-vuls: %v\n", err)
+		os.Exit(1)
+	}
+}
+
+func readInput(path string) ([]byte, error) {
+	if path == "" {
+		return ioutil.ReadAll(os.Stdin)
+	}
+	return ioutil.ReadFile(path)
+}
