new file mode 100644
index 0000000..e40ac9f
--- /dev/null
+++ b/contrib/trivy/parser/parser.go
@@ -0,0 +1,119 @@
+package parser
+
+import (
+	"encoding/json"
+	"sort"
+	"strings"
+
+	"github.com/future-architect/vuls/models"
+)
+
+type trivyReport struct {
+	ArtifactName string `json:"ArtifactName"`
+	Metadata     struct {
+		OS struct {
+			Family string `json:"Family"`
+			Name   string `json:"Name"`
+		} `json:"OS"`
+	} `json:"Metadata"`
+	Results []trivyResult `json:"Results"`
+}
+
+type trivyResult struct {
+	Target          string               `json:"Target"`
+	Type            string               `json:"Type"`
+	Vulnerabilities []trivyVulnerability `json:"Vulnerabilities"`
+}
+
+type trivyVulnerability struct {
+	VulnerabilityID  string   `json:"VulnerabilityID"`
+	PkgName          string   `json:"PkgName"`
+	InstalledVersion string   `json:"InstalledVersion"`
+	FixedVersion     string   `json:"FixedVersion"`
+	Severity         string   `json:"Severity"`
+	References       []string `json:"References"`
+}
+
+var supportedTrivyTypes = map[string]bool{
+	"apk": true, "deb": true, "rpm": true, "npm": true, "composer": true,
+	"pip": true, "pipenv": true, "bundler": true, "cargo": true,
+}
+
+// Parse converts a Trivy JSON report into the public Vuls ScanResult model.
+func Parse(vulnJSON []byte, scanResult *models.ScanResult) (*models.ScanResult, error) {
+	var report trivyReport
+	if err := json.Unmarshal(vulnJSON, &report); err != nil {
+		return nil, err
+	}
+	if scanResult == nil {
+		scanResult = &models.ScanResult{}
+	}
+	scanResult.ServerName = report.ArtifactName
+	scanResult.Family = report.Metadata.OS.Family
+	scanResult.Release = report.Metadata.OS.Name
+	if scanResult.Packages == nil {
+		scanResult.Packages = models.Packages{}
+	}
+	if scanResult.ScannedCves == nil {
+		scanResult.ScannedCves = models.VulnInfos{}
+	}
+
+	for _, result := range report.Results {
+		ecosystem := strings.ToLower(result.Type)
+		if !supportedTrivyTypes[ecosystem] {
+			continue
+		}
+		if scanResult.ServerName == "" {
+			scanResult.ServerName = result.Target
+		}
+		for _, vuln := range result.Vulnerabilities {
+			if vuln.VulnerabilityID == "" || vuln.PkgName == "" {
+				continue
+			}
+			scanResult.Packages[vuln.PkgName] = models.Package{
+				Name:       vuln.PkgName,
+				Version:    vuln.InstalledVersion,
+				NewVersion: vuln.FixedVersion,
+			}
+			content := models.CveContent{
+				Type:          models.Trivy,
+				CveID:         vuln.VulnerabilityID,
+				Title:         vuln.VulnerabilityID,
+				Summary:       vuln.PkgName + " in " + result.Target,
+				Cvss3Severity: strings.ToUpper(vuln.Severity),
+				References:    trivyReferences(vuln.References),
+			}
+			scanResult.ScannedCves[vuln.VulnerabilityID] = models.VulnInfo{
+				CveID: vuln.VulnerabilityID,
+				AffectedPackages: models.PackageFixStatuses{{
+					Name:    vuln.PkgName,
+					FixedIn: vuln.FixedVersion,
+				}},
+				CveContents: models.CveContents{
+					models.Trivy: content,
+				},
+			}
+		}
+	}
+	return scanResult, nil
+}
+
+func trivyReferences(values []string) models.References {
+	seen := map[string]bool{}
+	for _, value := range values {
+		value = strings.TrimSpace(value)
+		if value != "" {
+			seen[value] = true
+		}
+	}
+	keys := make([]string, 0, len(seen))
+	for value := range seen {
+		keys = append(keys, value)
+	}
+	sort.Strings(keys)
+	refs := make(models.References, 0, len(keys))
+	for _, value := range keys {
+		refs = append(refs, models.Reference{Source: "trivy", Link: value})
+	}
+	return refs
+}
