+// UploadToFutureVuls sends a Vuls ScanResult to a FutureVuls endpoint.
+func UploadToFutureVuls(scanResult models.ScanResult, endpoint, token string, groupID int64) error {
+	body, err := json.Marshal(struct {
+		GroupID    int64             `json:"GroupID"`
+		ScanResult models.ScanResult `json:"ScanResult"`
+	}{
+		GroupID:    groupID,
+		ScanResult: scanResult,
+	})
+	if err != nil {
+		return xerrors.Errorf("Failed to Marshal FutureVuls JSON: %w", err)
+	}
+	req, err := http.NewRequest("POST", endpoint, bytes.NewReader(body))
+	if err != nil {
+		return err
+	}
+	req.Header.Set("Authorization", "Bearer "+token)
+	req.Header.Set("Content-Type", "application/json")
+
+	resp, err := http.DefaultClient.Do(req)
+	if err != nil {
+		return err
+	}
+	defer resp.Body.Close()
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		data, _ := ioutil.ReadAll(resp.Body)
+		return xerrors.Errorf("FutureVuls upload failed with StatusCode %d: %s", resp.StatusCode, strings.TrimSpace(string(data)))
+	}
+	return nil
+}
