+func (deb Debian) debianSeverity(cve *gostmodels.DebianCVE) string {
+	seen := map[string]string{}
+	for _, p := range cve.Package {
+		for _, r := range p.Release {
+			urgency := strings.TrimSpace(r.Urgency)
+			if urgency == "" {
+				continue
+			}
+			key := strings.ToLower(urgency)
+			if _, ok := seen[key]; !ok {
+				seen[key] = key
+			}
+		}
+	}
+	severities := make([]string, 0, len(seen))
+	for _, severity := range seen {
+		severities = append(severities, severity)
+	}
+	sort.Slice(severities, func(i, j int) bool {
+		cmp := deb.CompareSeverity(severities[i], severities[j])
+		if cmp != 0 {
+			return cmp < 0
+		}
+		return severities[i] < severities[j]
+	})
+	return strings.Join(severities, "|")
+}
+
+func (deb Debian) CompareSeverity(a string, b string) int {
+	return debianSeverityRank(a) - debianSeverityRank(b)
+}
+
+func debianSeverityRank(severity string) int {
+	switch strings.ToLower(strings.TrimSpace(severity)) {
+	case "unknown":
+		return 10
+	case "unimportant":
+		return 20
+	case "not yet assigned":
+		return 30
+	case "end-of-life":
+		return 40
+	case "low":
+		return 50
+	case "medium":
+		return 60
+	case "high":
+		return 70
+	}
+	return 0
+}
