+func (o *alpine) parseApkIndex(stdout string) (models.Packages, models.SrcPackages, error) {
+	packs := models.Packages{}
+	srcs := models.SrcPackages{}
+	name, version, arch, srcName := "", "", "", ""
+	flush := func() error {
+		if name == "" {
+			return nil
+		}
+		if version == "" {
+			return xerrors.Errorf("Failed to parse APKINDEX record for %s: missing version", name)
+		}
+		if srcName == "" {
+			srcName = name
+		}
+		packs[name] = models.Package{Name: name, Version: version, Arch: arch}
+		addAlpineSrcPackage(srcs, srcName, version, name)
+		name, version, arch, srcName = "", "", "", ""
+		return nil
+	}
+	scanner := bufio.NewScanner(strings.NewReader(stdout))
+	for scanner.Scan() {
+		line := strings.TrimSpace(scanner.Text())
+		if line == "" {
+			if err := flush(); err != nil {
+				return nil, nil, err
+			}
+			continue
+		}
+		if len(line) < 3 || line[1] != ':' {
+			continue
+		}
+		value := strings.TrimSpace(line[2:])
+		switch line[0] {
+		case 'P':
+			if name != "" {
+				if err := flush(); err != nil {
+					return nil, nil, err
+				}
+			}
+			name = value
+		case 'V':
+			version = value
+		case 'A':
+			arch = value
+		case 'o':
+			srcName = value
+		}
+	}
+	if err := scanner.Err(); err != nil {
