+	if _, err := l.svc.UpdateTable(&c); err != nil {
+		return trace.Wrap(convertError(err))
+	}
+
+	// If we hit this time, we give up waiting.
+	waitStart := time.Now()
+	endWait := waitStart.Add(time.Minute * 10)
+
