+limitations under the License.
+*/
+
+package model
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+	"github.com/sashabaranov/go-openai"
+	"github.com/tiktoken-go/tokenizer/codec"
+)
+
+// Ref: https://github.com/openai/openai-cookbook/blob/594fc6c952425810e9ea5bd1a275c8ca5f32e8f9/examples/How_to_count_tokens_with_tiktoken.ipynb
+const (
+	// perMessage is the token overhead for each message.
+	perMessage = 3
+
+	// perRequest is the number of tokens used for each completion request.
+	perRequest = 3
+
+	// perRole is the number of tokens used to encode a message's role.
+	perRole = 1
+)
+
+var defaultTokenizer = codec.NewCl100kBase()
+
+// TokenCount holds token counters for both prompt and completion tokens.
+// Each model call made by an agent contributes one counter of each kind.
+type TokenCount struct {
+	Prompt     TokenCounters
+	Completion TokenCounters
+}
+
+// AddPromptCounter adds a counter to the prompt list. Nil counters are ignored.
+func (tc *TokenCount) AddPromptCounter(prompt TokenCounter) {
+	if prompt != nil {
+		tc.Prompt = append(tc.Prompt, prompt)
+	}
+}
+
+// AddCompletionCounter adds a counter to the completion list. Nil counters are ignored.
+func (tc *TokenCount) AddCompletionCounter(completion TokenCounter) {
+	if completion != nil {
+		tc.Completion = append(tc.Completion, completion)
+	}
+}
+
+// CountAll returns the prompt and completion totals, in that order.
+func (tc *TokenCount) CountAll() (int, int) {
+	return tc.Prompt.CountAll(), tc.Completion.CountAll()
+}
+
+// NewTokenCount returns an empty token count.
+func NewTokenCount() *TokenCount {
+	return &TokenCount{
+		Prompt:     TokenCounters{},
+		Completion: TokenCounters{},
+	}
+}
+
+// TokenCounter is implemented by synchronous and streaming token counters.
+// TokenCount must be idempotent.
+type TokenCounter interface {
+	TokenCount() int
+}
+
+// TokenCounters is a collection of token counters.
+type TokenCounters []TokenCounter
+
+// CountAll returns the sum of all counters.
+func (tc TokenCounters) CountAll() int {
+	var total int
+	for _, counter := range tc {
+		total += counter.TokenCount()
+	}
+	return total
+}
+
+// StaticTokenCounter is a token count that has already been evaluated.
+type StaticTokenCounter int
+
+// TokenCount returns the stored token count.
+func (tc *StaticTokenCounter) TokenCount() int {
+	return int(*tc)
+}
+
+// NewPromptTokenCounter counts the tokens used by a prompt.
+func NewPromptTokenCounter(prompt []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
+	var promptCount int
+	for _, message := range prompt {
+		promptTokens, _, err := defaultTokenizer.Encode(message.Content)
+		if err != nil {
+			return nil, trace.Wrap(err)
+		}
+		promptCount += perMessage + perRole + len(promptTokens)
+	}
+
+	counter := StaticTokenCounter(promptCount)
+	return &counter, nil
+}
+
+// NewSynchronousTokenCounter counts the tokens used by a completed response.
+func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
+	completionTokens, _, err := defaultTokenizer.Encode(completion)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	counter := StaticTokenCounter(perRequest + len(completionTokens))
+	return &counter, nil
+}
+
+// AsynchronousTokenCounter counts tokens received from a streamed completion.
+type AsynchronousTokenCounter struct {
+	mu       sync.Mutex
+	count    int
+	finished bool
+}
+
+// Add records one streamed token. Once TokenCount has been observed, the
+// counter is finalized and no more tokens may be added.
+func (tc *AsynchronousTokenCounter) Add() error {
+	tc.mu.Lock()
+	defer tc.mu.Unlock()
+
+	if tc.finished {
+		return trace.Errorf("count is already finished, cannot add more content")
+	}
+	tc.count++
+	return nil
+}
+
+// TokenCount finalizes the counter and returns its current total. It is
+// idempotent and never waits for the producer of a stream.
+func (tc *AsynchronousTokenCounter) TokenCount() int {
+	tc.mu.Lock()
+	defer tc.mu.Unlock()
+
+	tc.finished = true
+	return perRequest + tc.count
+}
+
+// NewAsynchronousTokenCounter creates a streaming counter and accounts for
+// any completion fragment that was received before the stream was exposed.
+func NewAsynchronousTokenCounter(completionStart string) (*AsynchronousTokenCounter, error) {
+	completionTokens, _, err := defaultTokenizer.Encode(completionStart)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &AsynchronousTokenCounter{count: len(completionTokens)}, nil
+}
