+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package native
+
+// #cgo CFLAGS: -Wall -xobjective-c -fblocks -fobjc-arc -mmacosx-version-min=10.13
+// #cgo LDFLAGS: -framework CoreFoundation -framework Foundation -framework IOKit -framework Security
+// #include <stdint.h>
+// #include <stdlib.h>
+// #include "device_darwin.h"
+import "C"
+
+import (
+	"crypto/sha256"
+	"crypto/x509"
+	"fmt"
+	"unsafe"
+
+	"github.com/google/uuid"
+	"github.com/gravitational/trace"
+	"google.golang.org/protobuf/types/known/timestamppb"
+
+	devicepb "github.com/gravitational/teleport/api/gen/proto/go/teleport/devicetrust/v1"
+	"github.com/gravitational/teleport/lib/darwin"
+)
+
+func enrollDeviceInit() (*devicepb.EnrollDeviceInit, error) {
+	cred, err := deviceKeyGetOrCreate()
+	if err != nil {
+		// TODO(codingllama): Show a nicer message if we are erroring because of an
+		//  unsigned/not-notarized binary.
+		return nil, trace.Wrap(err)
+	}
+
+	cd, err := collectDeviceData()
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &devicepb.EnrollDeviceInit{
+		CredentialId: cred.Id,
+		DeviceData:   cd,
+		Macos: &devicepb.MacOSEnrollPayload{
+			PublicKeyDer: cred.PublicKeyDer,
+		},
+	}, nil
+}
+
+func deviceKeyGetOrCreate() (*devicepb.DeviceCredential, error) {
+	newID := uuid.NewString()
+	newIDC := C.CString(newID)
+	defer C.free(unsafe.Pointer(newIDC))
+
+	var pubKeyC C.PublicKey
+	defer func() {
+		C.free(unsafe.Pointer(pubKeyC.id))
+		C.free(unsafe.Pointer(pubKeyC.pub_key))
+	}()
+
+	if res := C.DeviceKeyGetOrCreate(newIDC, &pubKeyC); res != 0 {
+		return nil, trace.Wrap(fmt.Errorf("creating device key: status %d", res))
+	}
+
+	id := C.GoString(pubKeyC.id)
+	pubKeyRaw := C.GoBytes(unsafe.Pointer(pubKeyC.pub_key), C.int(pubKeyC.pub_key_len))
+	return pubKeyToCredential(id, pubKeyRaw)
+}
+
+func pubKeyToCredential(id string, pubKeyRaw []byte) (*devicepb.DeviceCredential, error) {
+	ecPubKey, err := darwin.ECDSAPublicKeyFromRaw(pubKeyRaw)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	pubKeyDER, err := x509.MarshalPKIXPublicKey(ecPubKey)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return &devicepb.DeviceCredential{
+		Id:           id,
+		PublicKeyDer: pubKeyDER,
+	}, nil
+}
+
+func collectDeviceData() (*devicepb.DeviceCollectedData, error) {
+	var dd C.DeviceData
+	defer func() { C.free(unsafe.Pointer(dd.serial_number)) }()
+
+	if res := C.DeviceCollectData(&dd); res != 0 {
+		return nil, trace.Wrap(fmt.Errorf("collecting device data: status %d", res))
+	}
+
+	return &devicepb.DeviceCollectedData{
+		CollectTime:  timestamppb.Now(),
+		OsType:       devicepb.OSType_OS_TYPE_MACOS,
+		SerialNumber: C.GoString(dd.serial_number),
+	}, nil
+}
+
+func signChallenge(chal []byte) (sig []byte, err error) {
+	h := sha256.Sum256(chal)
+	digC := C.Digest{
+		data:     (*C.uint8_t)(C.CBytes(h[:])),
+		data_len: (C.size_t)(len(h)),
+	}
+	defer func() { C.free(unsafe.Pointer(digC.data)) }()
+
+	var sigC C.Signature
+	defer func() { C.free(unsafe.Pointer(sigC.data)) }()
+
+	if res := C.DeviceKeySign(digC, &sigC); res != 0 {
+		return nil, trace.Wrap(fmt.Errorf("signing with device key: status %d", res))
+	}
+
+	sig = C.GoBytes(unsafe.Pointer(sigC.data), C.int(sigC.data_len))
+	return sig, err
+}
diff --git a/lib/devicetrust/native/device_darwin.h b/lib/devicetrust/native/device_darwin.h
new file mode 100644
index 0000000000000000000000000000000000000000..3bb1774142b0ad92b693994b73c4cbb383e0bbcc
--- /dev/null
+++ b/lib/devicetrust/native/device_darwin.h
@@ -0,0 +1,54 @@
+#ifndef DEVICE_DARWIN_H_
+#define DEVICE_DARWIN_H_
+
+#include <stddef.h>
+#include <stdint.h>
+
+// PublicKey represents a device public key, containing its credential ID and
+// binary representation (as returned by SecKeyCopyExternalRepresentation).
+// A device key is guaranteed to be stored in the Secure Enclave, and thus is an
+// ECDSA P-256 key.
+typedef struct PublicKey {
+  const char *id;
+  uint8_t *pub_key;
+  size_t pub_key_len;
+} PublicKey;
+
+struct _Bytes {
+  uint8_t *data;
+  size_t data_len;
+};
+
+// Digest is a hash digest to be signed.
+typedef struct _Bytes Digest;
+
+// Signature is a signature over a Digest.
+typedef struct _Bytes Signature;
+
+// DeviceKeyGetOrCreate creates a new Secure Enclave key for the device, or
+// returns the existing key if one is already present.
+// Callers are responsible for allocating and freeing all "out" parameters.
+// Returns zero for success, non-zero for failures (likely an OSStatus value).
+int32_t DeviceKeyGetOrCreate(const char *newID, PublicKey *pubKeyOut);
+
+// DeviceKeyGet returns the current device key or fails.
+// Callers are responsible for allocating and freeing all "out" parameters.
+// Returns zero for success, non-zero for failures (likely an OSStatus value).
+int32_t DeviceKeyGet(PublicKey *pubKeyOut);
+
+// DeviceKeySign signs digest using the device key.
+// Callers are responsible for allocating and freeing all "out" parameters.
+// Returns zero for success, non-zero for failures (likely an OSStatus value).
+int32_t DeviceKeySign(Digest digest, Signature *sigOut);
+
+// DeviceData contains collected data for the device in use.
+typedef struct _DeviceData {
+  const char *serial_number;
+} DeviceData;
+
+// DeviceCollectData collects data for the device in use.
+// Callers are responsible for allocating and freeing all "out" parameters.
+// Returns zero for success, non-zero for failures.
+int32_t DeviceCollectData(DeviceData *out);
+
+#endif // DEVICE_DARWIN_H_
diff --git a/lib/devicetrust/native/device_darwin.m b/lib/devicetrust/native/device_darwin.m
new file mode 100644
index 0000000000000000000000000000000000000000..fec6dcfda65dfb78d96273290fd4e26778cc978a
--- /dev/null
+++ b/lib/devicetrust/native/device_darwin.m
@@ -0,0 +1,267 @@
+// Copyright 2022 Gravitational, Inc
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use this file except in compliance with the License.
+// You may obtain a copy of the License at
+//
+//      http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+#include "device_darwin.h"
+
+#import <CoreFoundation/CoreFoundation.h>
+#import <Foundation/Foundation.h>
+#import <IOKit/IOKitLib.h>
+#import <Security/Security.h>
+
+#include <stdlib.h>
+#include <string.h>
+
+const char *kDeviceKeyLabel = "com.gravitational.teleport.devicekey";
+
+const int kErrNoApplicationTag = 1;
+const int kErrNoValueRef = 2;
+const int kErrCopyPubKeyFailed = 3;
+const int kErrIOMatchingServiceFailed = 4;
+const int kErrIORegistryEntryFailed = 5;
+
+OSStatus findDeviceKey(NSNumber *retAttrs, CFTypeRef *out) {
+  NSData *label = [NSData dataWithBytes:(void *)kDeviceKeyLabel
+                                 length:strlen(kDeviceKeyLabel)];
+  NSDictionary *query = @{
+    (id)kSecClass : (id)kSecClassKey,
+    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+    (id)kSecMatchLimit : (id)kSecMatchLimitOne,
+    (id)kSecReturnRef : @YES,
+    (id)kSecReturnAttributes : (id)retAttrs,
+    (id)kSecAttrApplicationLabel : label,
+  };
+  return SecItemCopyMatching((CFDictionaryRef)query, out);
+}
+
+void copyPublicKey(const char *id, CFDataRef pubKeyRep, PublicKey *pubKeyOut) {
+  pubKeyOut->id = strdup(id);
+  pubKeyOut->pub_key_len = CFDataGetLength(pubKeyRep);
+  pubKeyOut->pub_key = calloc(pubKeyOut->pub_key_len, sizeof(uint8_t));
+  memcpy(pubKeyOut->pub_key, CFDataGetBytePtr(pubKeyRep),
+         pubKeyOut->pub_key_len);
+}
+
+int32_t DeviceKeyGetOrCreate(const char *newID, PublicKey *pubKeyOut) {
+  CFErrorRef err = NULL;
+  SecAccessControlRef access = NULL;
+  NSString *label = NULL;     // managed by ARC
+  NSData *labelAsData = NULL; // managed by ARC
+  NSData *idAsData = NULL;    // managed by ARC
+  NSDictionary *attrs = NULL; // managed by ARC
+  SecKeyRef privKey = NULL;
+  SecKeyRef pubKey = NULL;
+  CFDataRef pubKeyRep = NULL;
+
+  // Unlike other checks, here we only proceed if the device key wasn't found.
+  // If DeviceKeyGet is successful, then a device key already exists.
+  // If DeviceKeyGet fails unexpectedly, then we pass that error forward and do
+  // not proceed.
+  int32_t res = DeviceKeyGet(pubKeyOut);
+  if (res != errSecItemNotFound) {
+    goto end;
+  }
+  res = 0; // default is that key creation works
+
+  access = SecAccessControlCreateWithFlags(
+      kCFAllocatorDefault, kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
+      kSecAccessControlPrivateKeyUsage, &err);
+  if (!access) {
+    res = CFErrorGetCode(err);
+    goto end;
+  }
+
+  label = [NSString stringWithUTF8String:kDeviceKeyLabel];
+  labelAsData = [NSData dataWithBytes:kDeviceKeyLabel
+                               length:strlen(kDeviceKeyLabel)];
+  idAsData = [NSData dataWithBytes:(void *)newID length:strlen(newID)];
+  attrs = @{
+    // Secure Enclave requires EC/256bit keys.
+    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+    (id)kSecAttrKeySizeInBits : @256,
+    (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
+
+    (id)kSecPrivateKeyAttrs : @{
+      (id)kSecAttrIsPermanent : @YES,
+      (id)kSecAttrAccessControl : (__bridge id)access,
+      // kSecAttrLabel is a human-readable label.
+      // CFStringRef
+      (id)kSecAttrLabel : label,
+      // kSecAttrApplicationLabel is used to lookup keys programatically.
+      // CFDataRef
+      (id)kSecAttrApplicationLabel : labelAsData,
+      // kSecAttrApplicationTag is a private application tag.
+      // CFDataRef
+      (id)kSecAttrApplicationTag : idAsData,
+    },
+  };
+  privKey = SecKeyCreateRandomKey((__bridge CFDictionaryRef)attrs, &err);
+  if (!privKey) {
+    res = CFErrorGetCode(err);
+    goto end;
+  }
+
+  pubKey = SecKeyCopyPublicKey(privKey);
+  if (!pubKey) {
+    res = kErrCopyPubKeyFailed;
+    goto end;
+  }
+
+  pubKeyRep = SecKeyCopyExternalRepresentation(pubKey, &err);
+  if (!pubKeyRep) {
+    res = CFErrorGetCode(err);
+    goto end;
+  }
+  copyPublicKey(newID, pubKeyRep, pubKeyOut);
+
+end:
+  if (pubKeyRep) {
+    CFRelease(pubKeyRep);
+  }
+  if (pubKey) {
+    CFRelease(pubKey);
+  }
+  if (privKey) {
+    CFRelease(privKey);
+  }
+  if (access) {
+    CFRelease(access);
+  }
+  if (err) {
+    CFRelease(err);
+  }
+  return res;
+}
+
+int32_t DeviceKeyGet(PublicKey *pubKeyOut) {
+  CFDictionaryRef attrs = NULL;
+  CFDataRef appTagData = NULL; // managed by attrs
+  NSString *appTag = NULL;     // managed by ARC
+  SecKeyRef privKey = NULL;    // managed by attrs
+  SecKeyRef pubKey = NULL;
+  CFErrorRef err = NULL;
+  CFDataRef pubKeyRep = NULL;
+
+  int32_t res = findDeviceKey(@YES /* retAttrs */, (CFTypeRef *)&attrs);
+  if (res != errSecSuccess) {
+    goto end;
+  }
+
+  appTagData = CFDictionaryGetValue(attrs, kSecAttrApplicationTag);
+  if (!appTagData) {
+    res = kErrNoApplicationTag;
+    goto end;
+  }
+  appTag = [[NSString alloc] initWithData:(__bridge NSData *)appTagData
+                                 encoding:NSUTF8StringEncoding];
+
+  privKey = (SecKeyRef)CFDictionaryGetValue(attrs, kSecValueRef);
+  if (!privKey) {
+    res = kErrNoValueRef;
+    goto end;
+  }
+
+  pubKey = SecKeyCopyPublicKey(privKey);
+  if (!pubKey) {
+    res = kErrCopyPubKeyFailed;
+    goto end;
+  }
+
+  pubKeyRep = SecKeyCopyExternalRepresentation(pubKey, &err);
+  if (!pubKeyRep) {
+    res = CFErrorGetCode(err);
+    goto end;
+  }
+  copyPublicKey([appTag UTF8String], pubKeyRep, pubKeyOut);
+
+end:
+  if (pubKeyRep) {
+    CFRelease(pubKeyRep);
+  }
+  if (err) {
+    CFRelease(err);
+  }
+  if (pubKey) {
+    CFRelease(pubKey);
+  }
+  if (attrs) {
+    CFRelease(attrs);
+  }
+  return res;
+}
+
+int32_t DeviceKeySign(Digest digest, Signature *sigOut) {
+  SecKeyRef privKey = NULL;
+  NSData *data = NULL; // managed by ARC
+  CFErrorRef err = NULL;
+  CFDataRef sig = NULL;
+
+  int32_t res = findDeviceKey(@NO /* retAttrs */, (CFTypeRef *)&privKey);
+  if (res != errSecSuccess) {
+    goto end;
+  }
+
+  data = [NSData dataWithBytes:digest.data length:digest.data_len];
+  sig = SecKeyCreateSignature(privKey,
+                              kSecKeyAlgorithmECDSASignatureDigestX962SHA256,
+                              (CFDataRef)data, &err);
+  if (!sig) {
+    res = CFErrorGetCode(err);
+    goto end;
+  }
+
+  sigOut->data_len = CFDataGetLength(sig);
+  sigOut->data = calloc(sigOut->data_len, sizeof(uint8_t));
+  memcpy(sigOut->data, CFDataGetBytePtr(sig), sigOut->data_len);
+
+end:
+  if (sig) {
+    CFRelease(sig);
+  }
+  if (err) {
+    CFRelease(err);
+  }
+  if (privKey) {
+    CFRelease(privKey);
+  }
+  return res;
+}
+
+int32_t DeviceCollectData(DeviceData *out) {
+  CFStringRef cfSerialNumber = NULL; // managed via bridge
+  NSString *serialNumber = NULL;     // managed by ARC
+  int32_t res = 0;
+
+  io_service_t platformExpert = IOServiceGetMatchingService(
+      0 /* mainPort */, IOServiceMatching("IOPlatformExpertDevice"));
+  if (!platformExpert) {
+    res = kErrIOMatchingServiceFailed;
+    goto end;
+  }
+
+  cfSerialNumber = IORegistryEntryCreateCFProperty(
+      platformExpert, CFSTR(kIOPlatformSerialNumberKey), kCFAllocatorDefault,
+      0 /* options */);
+  if (!cfSerialNumber) {
+    res = kErrIORegistryEntryFailed;
+    goto end;
+  }
+  serialNumber = (__bridge_transfer NSString *)cfSerialNumber;
+  out->serial_number = strdup([serialNumber UTF8String]);
+
+end:
+  if (platformExpert) {
+    IOObjectRelease(platformExpert);
+  }
+  return res;
+}
