+func buildKubeConfigUpdate(ctx context.Context, tc *client.TeleportClient, tshBinary string) (kubeconfig.Values, bool, error) {
+	values := kubeconfig.Values{
+		ClusterAddr: tc.KubeClusterAddr(),
