+	values.TeleportClusterName, _ = tc.KubeProxyHostPort()
+	if tc.SiteName != "" {
+		values.TeleportClusterName = tc.SiteName
+	}
+	var err error
+	values.Credentials, err = tc.LocalAgent().GetCoreKey()
+	if err != nil {
+		return values, false, trace.Wrap(err)
+	}
+
+	if _, err := tc.Ping(ctx); err != nil {
+		return values, false, trace.Wrap(err)
+	}
