+// ErrLimitReached indicates that unread input remains after a bounded read.
+var ErrLimitReached = errors.New("read limit reached")
+
+// ReadAtMost reads all available input up to limit bytes.
+func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
+	if limit < 0 {
+		return nil, ErrLimitReached
+	}
+	data, err := ioutil.ReadAll(io.LimitReader(r, limit+1))
+	if err != nil {
+		return data, err
+	}
+	if int64(len(data)) > limit {
+		return data[:limit], ErrLimitReached
+	}
+	return data, nil
+}

