+type crlfWriter struct {
+	writer   io.Writer
+	previous byte
+}
+
+// CRLFWriter wraps a writer and converts bare LF line endings to CRLF.
+func CRLFWriter(w io.Writer) io.Writer {
+	return &crlfWriter{writer: w}
+}
+
+func (w *crlfWriter) Write(p []byte) (int, error) {
+	converted := make([]byte, 0, len(p))
+	previous := w.previous
+	for _, current := range p {
+		if current == '\n' && previous != '\r' {
+			converted = append(converted, '\r')
+		}
+		converted = append(converted, current)
+		previous = current
+	}
+
+	n, err := w.writer.Write(converted)
+	if err != nil {
+		return 0, err
+	}
+	if n != len(converted) {
+		return 0, io.ErrShortWrite
+	}
+	w.previous = previous
+	return len(p), nil
+}
