+
+// GetInstance returns the singleton value for T, constructing it on first use.
+func GetInstance[T any](constructor func() T) T {
+	typeKey := reflect.TypeOf((*T)(nil)).Elem()
+	entryValue, _ := typedInstances.LoadOrStore(typeKey, &typedEntry{})
+	entry := entryValue.(*typedEntry)
+	entry.once.Do(func() {
+		entry.value = constructor()
+		log.Trace("Created new typed singleton", "object", typeKey.String(), "instance", entry.value)
+	})
+	return entry.value.(T)
+}

