@@ -0,0 +1,30 @@
+export type MetricsApiStatusTypes = '4xx' | '5xx' | 'failure';
+
+type MetricObserver = (value: MetricsApiStatusTypes) => void;
+
+const statusCodeFromError = (error: unknown): number | null => {
+    if (error == null || typeof error !== 'object' || !('status' in error)) {
+        return null;
+    }
+    const rawStatus = (error as { status?: unknown }).status;
+    if (typeof rawStatus === 'number' && Number.isInteger(rawStatus)) {
+        return rawStatus;
+    }
+    if (typeof rawStatus === 'string' && /^\d+$/.test(rawStatus)) {
+        return Number(rawStatus);
+    }
+    return null;
+};
+
+export const observeApiError = (error: unknown, metricObserver: MetricObserver) => {
+    const status = statusCodeFromError(error);
+    if (status != null && status >= 400 && status <= 499) {
+        metricObserver('4xx');
+        return;
+    }
+    if (status != null && status >= 500 && status <= 599) {
+        metricObserver('5xx');
+        return;
+    }
+    metricObserver('failure');
+};
