+        Token,
+        api,
+        ApprovalURL,
+        ReturnHost,
+        signal,
+    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
+        api: Api;
+        signal: AbortSignal;
+    },
+    delayListening = DELAY_LISTENING
