+                        return resolve();
+                    }
+                    throw new Error(c('Error').t`Tab closed`);
+                } catch (error: any) {
+                    return reject({ ...error, tryAgain: true });
+                }
+            }
+
+            await wait(delayListening);
+            return listenTab();
+        };
