+
+function removeTechnicalFieldsFromObject(object: Record<string, unknown>): void {
+	for (const [key, value] of Object.entries(object)) {
+		if (TECHNICAL_FIELD_PREFIXES.some((prefix) => key.startsWith(prefix))) {
+			delete object[key]
+		} else if (value !== null && typeof value === "object") {
+			removeTechnicalFieldsFromObject(value as Record<string, unknown>)
+		}
+	}
+}

